import json

from taf.internal.sw.dcap.rd.client.dcap_lite.v3.models.trace_profile_tracer import TraceProfileTracer
from taf.internal.sw.dcap.rd.client.dcap_lite.v3.models.provided_trace import ProvidedTrace


class CustomBTSTraceProfile(object):
    def __init__(self, requirements, **kwargs):
        super(CustomBTSTraceProfile, self).__init__()
        self.custom_trace_profile = self._generate_custom_bts_trace_profile(requirements=requirements,
                                                                            trace_type="BTS",
                                                                            **kwargs)

    def _generate_custom_bts_trace_profile(self, requirements, trace_type, **kwargs):
        tracers = []
        for requirement in requirements:
            tracers += self.custom_bts_tracers(custom_profile=requirement,
                                               trace_type=trace_type,
                                               **kwargs)
        return tracers

    @staticmethod
    def custom_bts_ip_capture(custom_bts_dict, **kwargs):
        bts_custom_profile = "ipCapture"
        kwargs['uplane_interface'] = kwargs.get('uplane_interface') or "False"
        kwargs['measurement_point'] = kwargs.get('measurement_point') or "NE_Terminated"
        return TraceProfileTracer(
            provided_traces=[ProvidedTrace(
                snapshot=False,
                trace=custom_bts_dict[bts_custom_profile].get('tracer_id'),
                type="BTS")],
            params=[
                {
                    "name": "measurementPoint",
                    "values": [
                        kwargs.get('measurement_point')
                    ]
                },
                {
                    "name": "uplaneCapturing",
                    "values": [
                        kwargs.get('uplane_interface')
                    ]
                }], type="BTS",
            name=custom_bts_dict[bts_custom_profile].get('name'),
            id=custom_bts_dict[bts_custom_profile].get('tracer_id'))

    @staticmethod
    def custom_bts_immediate_snapshot(custom_bts_dict, **kwargs):
        bts_custom_profile = "immediateSnapshot"
        params = []
        if kwargs.get('collection_timing') is not None:
            params.append(
                {
                    "name": "snapshotMode",
                    "values": kwargs.get('collection_timing').split(",")
                })
        if kwargs.get('snapshot_coverage') is not None:
            params.append(
                {
                    "name": "snapshotCoverage",
                    "values": [kwargs.get('snapshot_coverage')]
                })
        return TraceProfileTracer(
            provided_traces=[ProvidedTrace(
                snapshot=False,
                trace=custom_bts_dict[bts_custom_profile].get('tracer_id'),
                type="BTS")],
            params=params, type="BTS",
            name=custom_bts_dict[bts_custom_profile].get('name'),
            id=custom_bts_dict[bts_custom_profile].get('tracer_id'))

    @staticmethod
    def format_values(**kwargs):
        if not kwargs.get('rad_values') and kwargs.get('persistency'):
            raise RuntimeError("rad_values and persistency are mandatory fields for RAD. Please provide them.")
        persistency = kwargs.get('persistency') or "Current"
        persistency_list = [value.strip() for value in persistency.split(',')]
        rad_values_list = [value.strip() for value in kwargs.get('rad_values').split(',')]
        permanent_list = [item.strip().lower() == "true" for item in (kwargs.get('permanent') or 'true').split(',')]

        lengths = [len(persistency_list), len(rad_values_list), len(permanent_list)]

        if len(set(lengths)) > 2 or (len(set(lengths)) == 2 and 1 not in lengths):
            raise ValueError(
                "Input values cannot be mapped. The number of values in persistency, rad_values, and "
                "permanent must match.")

        formatted_dicts = []
        for i in range(len(rad_values_list)):
            persistency = persistency_list[i] if i < len(persistency_list) else persistency_list[-1]
            rad_values = rad_values_list[i] if i < len(rad_values_list) else rad_values_list[-1]
            permanent = permanent_list[i] if i < len(permanent_list) else permanent_list[-1]

            formatted_dict = {
                'persistency': persistency,
                'params': [rad_values],
                'permanent': permanent
            }

            formatted_dict_str = json.dumps(formatted_dict)
            formatted_dicts.append(formatted_dict_str)

        return formatted_dicts

    @staticmethod
    def custom_bts_rad_params(custom_bts_dict, **kwargs):
        bts_custom_profile = "rad"
        formatted_values = CustomBTSTraceProfile.format_values(**kwargs)
        return TraceProfileTracer(
            provided_traces=[ProvidedTrace(
                snapshot=False,
                trace=custom_bts_dict[bts_custom_profile].get('tracer_id'),
                type="BTS")],
            params=[
                {
                    "name": "syscomRadParams",
                    "values": formatted_values
                }], type="BTS",
            name=custom_bts_dict[bts_custom_profile].get('name'),
            id=custom_bts_dict[bts_custom_profile].get('tracer_id'))

    @staticmethod
    def format_tss_values(script_names, cells, bbmods=None, rmods=None, free_text_parameters=None):
        if not script_names and cells:
            raise RuntimeError("script_names and cells are mandatory fields for TSS. Please provide them.")
        script_names_list = [name.strip() for name in script_names.split(',')]
        cells_list = [cell.strip() for cell in cells.split(',')]
        bbmods_list = [bbmod.strip() for bbmod in (bbmods.split(',') if bbmods else [])]
        rmods_list = [rmod.strip() for rmod in (rmods.split(',') if rmods else [])]

        return [json.dumps({
            "scriptName": script_name,
            "cells": cells_list,
            "bbmods": bbmods_list,
            "rmods": rmods_list,
            "freeTextParameters": free_text_parameters or ""
        }) for script_name in script_names_list]

    @staticmethod
    def custom_bts_tss(custom_bts_dict, bts_Id=None, script_names=None, cells=None,
                       bbmods=None, rmods=None, free_text_parameters=None, type="BTS", **kwargs):
        formatted_values = CustomBTSTraceProfile.format_tss_values(script_names, cells, bbmods, rmods,
                                                                   free_text_parameters)
        bts_custom_profile = "tss"
        return TraceProfileTracer(
            provided_traces=[ProvidedTrace(
                snapshot=False,
                trace=custom_bts_dict[bts_custom_profile].get('tracer_id'),
                type=type)],
            params=[
                {
                    "name": bts_Id,
                    "values": formatted_values
                }], type=type,
            name=custom_bts_dict[bts_custom_profile].get('name'),
            id=custom_bts_dict[bts_custom_profile].get('tracer_id'))

    @staticmethod
    def custom_bts_screl(custom_bts_dict, **kwargs):
        bts_custom_profile = "screlBts"
        kwargs['screl_coverage_bts'] = kwargs.get('screl_coverage_bts') or "default"
        return TraceProfileTracer(
            provided_traces=[ProvidedTrace(
                snapshot=False,
                trace=custom_bts_dict[bts_custom_profile].get('tracer_id'),
                type="BTS")],
            params=[
                {
                    "name": "screlCoverage",
                    "values": [
                        kwargs['screl_coverage_bts']
                    ]
                }], type="BTS",
            name=custom_bts_dict[bts_custom_profile].get('name'),
            id=custom_bts_dict[bts_custom_profile].get('tracer_id'))

    @staticmethod
    def custom_bts_event_based_tracer(custom_bts_dict, **kwargs):
        bts_custom_profile = 'BTSeventBasedTracer'
        return TraceProfileTracer(
            provided_traces=[ProvidedTrace(
                snapshot=False,
                trace=custom_bts_dict[bts_custom_profile].get('tracer_id'),
                type='BTS')],
            params=[],
            type='BTS',
            name=custom_bts_dict[bts_custom_profile].get('name'),
            id=custom_bts_dict[bts_custom_profile].get('tracer_id'))

    @staticmethod
    def custom_bts_pm_files(custom_bts_dict, **kwargs):
        """
        Custom PM file collection with filter options.

        :param dict custom_bts_dict: Dictionary containing PM file tracer configuration
        :param str pm_collection_timing: Collection timing option, default "start,end"
                                   Options: "start", "end", "start,end"
        """
        bts_custom_profile = 'pmFiles'
        params = []
        if kwargs.get('pm_collection_timing') is not None:
            params.append(
                {
                    "name": "pmFilesMode",
                    "values": kwargs.get('pm_collection_timing').split(',')
                })

        return TraceProfileTracer(
            provided_traces=[ProvidedTrace(
                snapshot=False,
                trace=custom_bts_dict[bts_custom_profile].get('tracer_id'),
                type="BTS")],
            params=params,
            type="BTS",
            name=custom_bts_dict[bts_custom_profile].get('name'),
            id=custom_bts_dict[bts_custom_profile].get('tracer_id'))

    def custom_bts_tracers(self, custom_profile, trace_type, **kwargs):
        custom_bts_dict = {'immediateSnapshot': {'name': 'Immediate snapshot', 'tracer_id': 'immediateSnapshot'},
                           'scf': {'tracer_id': 'scf', 'name': 'SCF'},
                           'pmFiles': {'tracer_id': 'pmFiles', 'name': 'PM Files'},
                           'ipCapture': {'tracer_id': 'ipCapture', 'name': 'Ip Capture'},
                           'rad': {'tracer_id': 'rad', 'name': 'BTS R&D Parameters'},
                           'tss': {'tracer_id': 'tss', 'name': 'BTS Troubleshooting scripts'},
                           'screlBts': {'tracer_id': 'screl', 'name': 'System critical event logs (SCREL)'},
                           'BTSeventBasedTracer': {'name': 'Event-based tracer', 'tracer_id': 'eventBasedTracer'}}
        custom_bts_profile_option = []

        profile_functions = {
            'ipCapture': self.custom_bts_ip_capture,
            'immediateSnapshot': self.custom_bts_immediate_snapshot,
            'rad': self.custom_bts_rad_params,
            'tss': self.custom_bts_tss,
            'screlBts': self.custom_bts_screl,
            'BTSeventBasedTracer': self.custom_bts_event_based_tracer,
            'pmFiles': self.custom_bts_pm_files
        }

        if custom_profile in profile_functions:
            custom_bts_profile_option.append(profile_functions[custom_profile](
                custom_bts_dict=custom_bts_dict,
                **kwargs))
        elif custom_profile in custom_bts_dict:
            custom_bts_profile_option.append(TraceProfileTracer(
                provided_traces=[ProvidedTrace(
                    snapshot=False,
                    trace=custom_bts_dict[custom_profile].get('tracer_id'),
                    type=trace_type)],
                params=[], type=trace_type,
                name=custom_bts_dict[custom_profile].get('name'),
                id=custom_bts_dict[custom_profile].get('tracer_id')))
        return custom_bts_profile_option
